// The grid is code: the agent cannot invent a rate.
const delay = Number(query.delay_days);
let compensation = 0;
if (delay >= 1 && delay <= 2) compensation = 5;
else if (delay >= 3 && delay <= 5) compensation = 10;
else if (delay > 5) compensation = 20;
return JSON.stringify({ compensation_percent: compensation, delay_days: delay, status: 'estimate, to be checked by the team' });

// The recipient comes from your site (webhook body), never from the chat.
// STUB: replace with your Gmail node, To = {{ $('Message').item.json.customer_email }}. Nothing is sent here.
const to = $('Message').first().json.customer_email;
if (!to) return JSON.stringify({ status: 'not sent', reason: 'no customer email on file for this session' });
return JSON.stringify({ status: 'sent', to, subject: query.subject });
